import { DEFAULT_LANG, LANGS, translations, type Lang } from "@/lib/i18n";
import { IMAGES, imagePreload, type ImageName } from "@/lib/images";
import { PHONE_DE_DISPLAY, PHONE_IT_DISPLAY } from "@/lib/contact";

export const SITE_URL = "https://venicelagoonbeachpoolcavallino.com";

// Social preview, generated by scripts/generate-meta-images.mjs
const OG_IMAGE = { url: `${SITE_URL}/og-image.jpg`, width: 1200, height: 630 };
const HERO: ImageName = "real-pool";

// Exact position of the building, 5+ decimals (Google requirement).
// TODO: fill in from Google Maps (right click on the building); omitted from the data until then.
const GEO: { latitude: number; longitude: number } | null = null;

const pathOf = (lang: Lang) => LANGS.find((l) => l.code === lang)!.path;

/** schema.org VacationRental: only facts stated on the page, no ratings or reviews. */
function vacationRental(lang: Lang) {
  const t = translations[lang];
  // Listing photos are the "real-*" images (not the map), hero first
  const names = Object.keys(IMAGES) as ImageName[];
  const photos = [HERO, ...names.filter((n) => n.startsWith("real-") && n !== HERO)];
  const amenity = (name: string, value: boolean | string = true) => ({
    "@type": "LocationFeatureSpecification",
    name,
    value,
  });
  return {
    "@context": "https://schema.org",
    "@type": "VacationRental",
    additionalType: "Apartment",
    // Must stay the same across languages and listing edits
    identifier: "venicelagoonbeachpoolcavallino",
    name: t.meta.title,
    description: t.meta.description,
    url: SITE_URL + pathOf(lang),
    telephone: lang === "de" ? PHONE_DE_DISPLAY : PHONE_IT_DISPLAY,
    image: photos.map((n) => `${SITE_URL}/img/${n}-${IMAGES[n].fallback}.jpg`),
    address: {
      "@type": "PostalAddress",
      streetAddress: "Via Paolo Thaon di Revel 58",
      addressLocality: "Cavallino-Treporti",
      addressRegion: "VE",
      postalCode: "30013",
      addressCountry: "IT",
    },
    ...(GEO ?? {}),
    containsPlace: {
      "@type": "Accommodation",
      additionalType: "EntirePlace",
      occupancy: { "@type": "QuantitativeValue", value: 4 },
      numberOfBedrooms: 1,
      floorSize: { "@type": "QuantitativeValue", value: 62, unitCode: "MTK" },
      // Google's amenity names (English in every language), matching the amenities section
      amenityFeature: [
        amenity("pool"),
        amenity("poolType", "Outdoor"),
        amenity("beachAccess"),
        amenity("ac"),
        amenity("kitchen"),
        amenity("wifi"),
        amenity("tv"),
        amenity("washerDryer"),
        amenity("selfCheckinCheckout"),
        amenity("balcony"),
        // TODO: amenity("licenseNum", CIN) once the real CIN replaces the placeholder in contact.ts
      ],
    },
  };
}

/**
 * head() of a landing page: title and description in the page language, absolute
 * canonical URL, reciprocal hreflang links (every page lists all languages),
 * social preview tags and structured data.
 */
export function pageHead(lang: Lang) {
  const { title, description } = translations[lang].meta;
  const url = SITE_URL + pathOf(lang);
  return {
    meta: [
      { title },
      { name: "description", content: description },
      { property: "og:title", content: title },
      { property: "og:description", content: description },
      { property: "og:url", content: url },
      { property: "og:locale", content: LANGS.find((l) => l.code === lang)!.ogLocale },
      { property: "og:image", content: OG_IMAGE.url },
      { property: "og:image:type", content: "image/jpeg" },
      { property: "og:image:width", content: String(OG_IMAGE.width) },
      { property: "og:image:height", content: String(OG_IMAGE.height) },
      { property: "og:image:alt", content: translations[lang].alt[HERO] },
      { "script:ld+json": vacationRental(lang) },
    ],
    links: [
      { rel: "canonical", href: url },
      ...LANGS.map((l) => ({ rel: "alternate", hrefLang: l.code, href: SITE_URL + l.path })),
      { rel: "alternate", hrefLang: "x-default", href: SITE_URL + pathOf(DEFAULT_LANG) },
      // Hero photo is the LCP element: start downloading it before the CSS is parsed.
      imagePreload(HERO, "100vw"),
    ],
  };
}
